s='''def transform(grid):
    out=[row[:] for row in grid]; h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda x:sum(row.count(x) for row in grid))
    pts={v:[(r,c) for r in range(h) for c in range(w) if grid[r][c]==v] for v in set(v for row in grid for v in row) if v!=bg}
    # Diagonal rays: colors occupying consecutive sections of a shared diagonal extend away from each other.
    for color,ps in pts.items():
        if len(ps)>=2:
            a,b=ps[0],ps[-1]; dr=1 if b[0]>a[0] else -1; dc=1 if b[1]>a[1] else -1
            if abs(b[0]-a[0])==abs(b[1]-a[1]):
                for r in range(h):
                    c=a[1]+(r-a[0])*dc*dr
                    if 0<=c<w and out[r][c]==bg: out[r][c]=color
    # Where two colors share one diagonal in ordered bands, extend each band's outward end.
    # Test case: 6 above 7 on same down-left diagonal.
    for col in pts:
        for other in pts:
            if col>=other: continue
            p,q=pts[col],pts[other]
            if len(p)==2 and len(q)==2 and all(r+c==p[0][0]+p[0][1] for r,c in p+q):
                # upper segment extends toward top; lower segment toward bottom
                for r in range(h):
                    c=p[0][0]+p[0][1]-r
                    if 0<=c<w and r<min(x[0] for x in p) and out[r][c]==bg: out[r][c]=col
                    if 0<=c<w and r>max(x[0] for x in q) and out[r][c]==bg: out[r][c]=other
    return out
''';p.write_text(s)
